using System.Linq;
using UnityEngine;
namespace FootballDynasty {
 public sealed class FootballAgent:MonoBehaviour {
  public float LastDecisionTime=-10;public bool IsSliding=>slideTime>0;private float slideTime,slideCooldown,aiTackleTimer,holdTime;private bool wonBall;private Vector3 slideDirection;private Transform visualRoot;private CapsuleCollider bodyCollider;public TacticalRole Role;public TacticalDecision Decision;public Vector3 FormationAnchor=>anchor;public Player Data;public int Team;public Rigidbody Body;public float Energy=100;private FootballSimulator game;private Vector3 anchor;private float kickCooldown;public FootballPlayerAnimator Animation;
  public float LeftLegAngle=>Animation.Pose.leftLeg;public float RightLegAngle=>Animation.Pose.rightLeg;
  public void Initialize(FootballSimulator owner,Player player,int team,int index,Color kit){game=owner;Data=player;Team=team;float sign=team==0?1:-1;var teamSheet=game.Career.Team(player.club);int slotIndex=System.Array.IndexOf(teamSheet.lineup,player.id);var slot=FormationLayout.Slots(teamSheet.formation)[slotIndex];anchor=new Vector3((-30+(.72f-slot.Y)/.62f*48)*sign,.9f,(slot.X-.5f)*65*sign);if(player.position=="POR")anchor.x=-49*sign;Role=game.Career.GetRole(player.id);transform.position=anchor;Body=gameObject.AddComponent<Rigidbody>();Body.mass=75;Body.constraints=RigidbodyConstraints.FreezeRotation;Body.interpolation=RigidbodyInterpolation.Interpolate;var capsule=gameObject.AddComponent<CapsuleCollider>();bodyCollider=capsule;capsule.radius=.3f;capsule.height=1.8f;var rig=new PlayerRig(transform,kit,game,Data.position=="POR");visualRoot=rig.Root;Animation=gameObject.AddComponent<FootballPlayerAnimator>();Animation.Initialize(this,game,rig); }
  public void RecoverAfterRelease(){kickCooldown=.9f;}
  public void PrepareRestart(){CancelSlide();kickCooldown=0;holdTime=0;}
  public void ResetPosition(){if(game.Hands.Owner==this)game.Hands.Drop();Animation.ResetPose();CancelSlide();LastDecisionTime=-10;Body.position=anchor;Body.linearVelocity=Vector3.zero;}
  public void CancelSlide(){slideTime=0;if(visualRoot)visualRoot.localRotation=Quaternion.identity;if(bodyCollider){bodyCollider.height=1.8f;bodyCollider.center=Vector3.zero;}}
  public void TrySlide(Vector3 direction){if(slideCooldown>0||IsSliding||!game.Running||game.IsCelebrating||game.Referee.HasRestart||Data.position=="POR")return;direction.y=0;if(direction.sqrMagnitude<.01f)direction=transform.forward;slideDirection=direction.normalized;slideTime=.55f;slideCooldown=2.4f;wonBall=false;Energy=Mathf.Max(0,Energy-8);bodyCollider.height=1;bodyCollider.center=new Vector3(0,-.35f,0);}
  public void Step(Vector3 input,bool human,bool sprint){if(game.Hands.Owner==this){Body.linearVelocity=Vector3.zero;var aim=human?input:new Vector3(Team==0?1:-1,0,0);if(aim.sqrMagnitude>.01f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(aim),Time.fixedDeltaTime*5);return;}slideCooldown=Mathf.Max(0,slideCooldown-Time.fixedDeltaTime);aiTackleTimer-=Time.fixedDeltaTime;
   if(IsSliding){slideTime-=Time.fixedDeltaTime;var from=Body.position;game.Referee.SlideContact(this,from,from+slideDirection*9*Time.fixedDeltaTime,ref wonBall);if(game.Referee.IsStopped)return;Body.linearVelocity=new Vector3(slideDirection.x*9,Body.linearVelocity.y,slideDirection.z*9);if(slideTime<=0)CancelSlide();return;}
   if(!human&&aiTackleTimer<=0&&game.Tactics.Possession.Team>=0&&game.Tactics.Possession.Team!=Team){var level=Data.club==game.ClubId?MatchDifficulty.Medio:game.Career.Difficulty;aiTackleTimer=DifficultySettings.TackleInterval(level);var towardBall=game.Ball.position-Body.position;towardBall.y=0;if(towardBall.magnitude<2.6f&&towardBall.magnitude>.8f&&Vector3.Angle(transform.forward,towardBall)<38)TrySlide(towardBall);}
   kickCooldown=Mathf.Max(0,kickCooldown-Time.fixedDeltaTime);float dir=Team==0?1:-1;Vector3 toward=input;if(!human){var target=new Vector3(Decision.Target.X,Body.position.y,Decision.Target.Z);toward=Vector3.ClampMagnitude(target-Body.position,1);sprint=Decision.Sprint;if(Vector3.Distance(Body.position,game.Ball.position)<1.2f){holdTime+=Time.fixedDeltaTime;if(dir*Body.position.x>27&&Mathf.Abs(Body.position.z)<18)Kick(false);else if(Data.position!="POR"&&(IsUnderPressure()||holdTime>1.7f||dir*Body.position.x>32))Kick(true);}}
   if(Data.position=="POR"&&kickCooldown<=0&&game.Hands.TryCatch(this))return;
   if(Data.position=="POR"&&kickCooldown<=0&&Vector3.Distance(Body.position,game.Ball.position)<1.5f&&game.Ball.position.y<1.8f){if(!game.Referee.Touch(this,false))return;var velocity=game.Ball.linearVelocity;game.Ball.linearVelocity=new Vector3(dir*(8+Data.stats.REF/10f),Mathf.Max(1,velocity.y*.25f),-game.Ball.position.z*.5f);kickCooldown=.8f;Animation.Trigger(PlayerAction.Save);}
   bool running=sprint&&Energy>10&&toward.sqrMagnitude>.1f;Energy=Mathf.Clamp(Energy+Time.fixedDeltaTime*(running?-4:1.7f),0,100);float speed=(4.3f+Data.stats.RIT/30f)*(running?1.4f:1)*(0.8f+Energy/500);var current=Body.linearVelocity;var desired=toward*speed;var planar=new Vector3(current.x,0,current.z);var next=Vector3.MoveTowards(planar,desired,Time.fixedDeltaTime*(toward.sqrMagnitude>.05f?11:15));Body.linearVelocity=new Vector3(next.x,current.y,next.z);if(toward.sqrMagnitude>.02f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(toward),Time.fixedDeltaTime*9);
   var pos=Body.position;float xLimit=Data.position=="POR"?52.4f:51.5f;pos.x=Mathf.Clamp(pos.x,-xLimit,xLimit);pos.z=Mathf.Clamp(pos.z,-33,33);Body.position=pos;if(Vector3.Distance(pos,game.Ball.position)<.95f&&kickCooldown<=0&&toward.sqrMagnitude>.1f){if(!game.Referee.Touch(this,true))return;var target=pos+toward.normalized*.7f;target.y=.13f;var delta=target-game.Ball.position;game.Ball.AddForce(Vector3.ClampMagnitude(delta*18,12),ForceMode.Acceleration);}
  }
  FootballAgent SelectPassTarget(){var actors=game.Agents.Select(a=>new TacticalPlayer{Team=a.Team,Position=new PitchPoint(a.Body.position.x,a.Body.position.z)}).ToArray();FootballAgent best=null;float score=float.MaxValue;foreach(var a in game.Agents)if(a.Team==Team&&a!=this&&a.Data.position!="POR"&&!game.Referee.WouldBeOffside(a,this)){var from=new PitchPoint(Body.position.x,Body.position.z);var to=new PitchPoint(a.Body.position.x,a.Body.position.z);float value=Passing.Score(from,to,Team,actors);if(value<score){score=value;best=a;}}return best;}
  bool IsUnderPressure(){foreach(var agent in game.Agents)if(agent.Team!=Team&&(agent.Body.position-Body.position).sqrMagnitude<6.25f)return true;return false;}
  public void Kick(bool pass){if(game.IsCelebrating)return;if(game.Hands.Owner==this){game.Hands.Release(pass);return;}if(game.Referee.HasRestart&&game.Referee.Kind==RestartKind.ThrowIn)pass=true;if(IsSliding||kickCooldown>0||Vector3.Distance(Body.position,game.Ball.position)>1.8f)return;FootballAgent receiver=null;float dir=Team==0?1:-1;Vector3 target=new Vector3(dir*55,.2f,0);float speed=24+Data.stats.TIR/8f;float lift=3.8f;if(pass){var mate=SelectPassTarget();if(!mate)return;receiver=mate;target=mate.Body.position+mate.Body.linearVelocity*.25f;target.x=Mathf.Clamp(target.x,-51,51);target.z=Mathf.Clamp(target.z,-32,32);speed=15+Data.stats.PAS/12f;lift=.4f;}if(!game.Referee.Kick(this))return;Animation.Trigger(game.Referee.LastRelease==RestartKind.ThrowIn?PlayerAction.ThrowIn:pass?PlayerAction.Pass:PlayerAction.Shoot);holdTime=0;if(receiver)game.ExpectReception(receiver);if(game.Referee.LastRelease==RestartKind.ThrowIn){game.Ball.position=Body.position+Vector3.up*1.15f;lift=4;target.z=Mathf.Clamp(target.z,-28,28);game.ResetBallTracking();}var vector=target-game.Ball.position;vector.y=0;float skill=pass?Data.stats.PAS:Data.stats.TIR;float error=(100-skill)*.045f*(1+(100-Energy)/100f);float turn=Vector3.Angle(transform.forward,vector);error*=1+turn/180f;if(Data.club!=game.ClubId)error*=DifficultySettings.AimError(game.Career.Difficulty);vector=Quaternion.Euler(0,Random.Range(-error,error),0)*vector;game.Ball.linearVelocity=vector.normalized*speed+Vector3.up*lift;game.Ball.angularVelocity=Vector3.Cross(Vector3.up,vector.normalized)*(pass?8:20)+Vector3.up*Random.Range(-3f,3f);kickCooldown=.75f;}
 }
}
